SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 3, 3), instr('Lambda', 'sigma'), replace('Lambda', 'a', ''), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE '_', 'Lambda' GLOB 'a*', char(90, 616), 'Lambda' || 'sigma', 'Lambda' < 'sigma', 'Lambda' = 'sigma' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', -2, 1), instr('xi', 'x_y'), replace('xi', 'a', 'XY'), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '%a_', 'xi' GLOB '*', char(77, 360), 'xi' || 'x_y', 'xi' < 'x_y', 'xi' = 'x_y' COLLATE NOCASE;
SELECT length('theta'), upper('theta'), lower('theta'), substr('theta', -2, 1), instr('theta', 'rho'), replace('theta', 'é', 'XY'), trim('theta'), ltrim('theta', 'ab'), hex('theta'), quote('theta'), unicode('theta'), 'theta' LIKE '%a_', 'theta' GLOB 'a*', char(79, 610), 'theta' || 'rho', 'theta' < 'rho', 'theta' = 'rho' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', 0, 2), instr('pi', 'upsilon'), replace('pi', 'e', 'XY'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE '_', 'pi' GLOB '*', char(78, 891), 'pi' || 'upsilon', 'pi' < 'upsilon', 'pi' = 'upsilon' COLLATE NOCASE;
SELECT length('omicron'), upper('omicron'), lower('omicron'), substr('omicron', -2, 3), instr('omicron', 'chi'), replace('omicron', '', ''), trim('omicron'), ltrim('omicron', 'ab'), hex('omicron'), quote('omicron'), unicode('omicron'), 'omicron' LIKE '%é%', 'omicron' GLOB '*[a-m]*', char(80, 748), 'omicron' || 'chi', 'omicron' < 'chi', 'omicron' = 'chi' COLLATE NOCASE;
SELECT length('über'), upper('über'), lower('über'), substr('über', 1, 1), instr('über', '0x1F'), replace('über', 'e', ''), trim('über'), ltrim('über', 'ab'), hex('über'), quote('über'), unicode('über'), 'über' LIKE '%é%', 'über' GLOB '*[a-m]*', char(86, 781), 'über' || '0x1F', 'über' < '0x1F', 'über' = '0x1F' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 0, 2), instr('sigma', 'alpha'), replace('sigma', 'a', ''), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE 'A%', 'sigma' GLOB '*[a-m]*', char(79, 923), 'sigma' || 'alpha', 'sigma' < 'alpha', 'sigma' = 'alpha' COLLATE NOCASE;
SELECT count(*), count(c0), sum(c0), total(c0), avg(c0), min(c0), max(c0), count(DISTINCT c0) FROM t1 WHERE typeof(CAST(id AS REAL));
SELECT c0, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY c0 ORDER BY c0;
